      SUBROUTINE INITLCC     INITIALIZES LIMITS ON VARIED PARAMETERSCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM39B.CIN'      INCLUDE 'ELM39D.CIN'CC----------------------------------------------------      DO 10 J = 1, 4   10 ALIM1(J) = ALM01(J)      DO 20 J = 1, 4   20 ALIM2(J) = ALM02(J)      DO 30 J = 1, 4   30 ALIM3(J) = ALM03(J)      DO 40 J = 1, 4      DO 40 K = 1, 6   40 ALIM4(J,K) = ALM04(J,K)      DO 50 J = 1, 4      DO 50 K = 1, 5   50 ALIM5(J,K) = ALM05(J,K)      DO 120 J = 1, 4      DO 120 K = 1, 15  120 ALIM12(J,K) = ALM012(J,K)      DO 180 J = 1, 4      DO 180 K = 1, 4  180 ALIM18(J,K) = ALM018(J,K)      DO 190 J = 1, 4      DO 190 K = 1, 3  190 ALIM19(J,K) = ALM019(J,K)      DO 200 J = 1, 4  200 ALIM20(J) = ALM020(J)      DO 250 J = 1, 4      DO 250 K = 1, 4  250 ALIM25(J,K) = ALM025(J,K)      DO 280 J = 1, 4      DO 280 K = 1, 13  280 ALIM28(J,K) = ALM028(J,K)      DO 340 J = 1, 4      DO 340 K = 1, 5  340 ALIM34(J,K) = ALM034(J,K)      DO 350 J = 1, 4      DO 350 K = 1, 3  350 ALIM35(J,K) = ALM035(J,K)      RETURN      END